/**
 * Todos los textos fijos de la app de clientes, en un único sitio.
 *
 * Para añadir un idioma (p. ej. neerlandés):
 *   1. Añádalo a `languages` (código, nombre corto, formato de fechas).
 *   2. Copie el bloque `en` como `nl` y traduzca los textos.
 *   3. En los datos de Firestore, los campos con sufijo `_nl` se usarán solos;
 *      si faltan, se muestra el inglés y, si tampoco hay, el español.
 *   4. Añada el código a la lista de idiomas válidos en firestore.rules, en functions/src/index.ts
 *      y en el selector de idioma del panel (src/lib/admin.ts).
 * El panel de administración no usa este archivo: está solo en español.
 */

export const languages = [
  { code: 'es', label: 'ES', name: 'Español', locale: 'es-ES' },
  { code: 'en', label: 'EN', name: 'English', locale: 'en-GB' },
  { code: 'nl', label: 'NL', name: 'Nederlands', locale: 'nl-NL' },
  { code: 'sv', label: 'SV', name: 'Svenska', locale: 'sv-SE' },
  { code: 'de', label: 'DE', name: 'Deutsch', locale: 'de-DE' },
  { code: 'fr', label: 'FR', name: 'Français', locale: 'fr-FR' },
  { code: 'pl', label: 'PL', name: 'Polski', locale: 'pl-PL' },
] as const

export type Language = (typeof languages)[number]['code']
export const defaultLanguage: Language = 'es'

/** Orden de reserva para textos de datos (_xx) que faltan: el idioma elegido, inglés y español */
export const dataFallback = (lang: Language): Language[] => [...new Set<Language>([lang, 'en', 'es'])]

